export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;

  type State = { windowStart: number; count: number };
  const states = new Map<string, State>();

  const getState = (key: string, nowMs: number): State => {
    const existing = states.get(key);
    if (!existing) {
      const newState: State = { windowStart: nowMs, count: 0 };
      states.set(key, newState);
      return newState;
    }
    if (nowMs - existing.windowStart >= windowMs) {
      existing.windowStart = nowMs;
      existing.count = 0;
    }
    return existing;
  };

  return {
    allow(key, nowMs) {
      const state = getState(key, nowMs);
      if (state.count < limit) {
        state.count++;
        return true;
      }
      return false;
    },

    remaining(key, nowMs) {
      const state = getState(key, nowMs);
      const remaining = limit - state.count;
      return remaining > 0 ? remaining : 0;
    },

    reset(key) {
      states.delete(key);
    },
  };
}
