export function createTtlCache(): TtlCache {
  const DEFAULT_TTL = 1000; // ms
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  const cleanIfExpired = (key: string, nowMs: number): boolean => {
    const entry = store.get(key);
    if (!entry) return false;
    if (nowMs >= entry.expiresAt) {
      store.delete(key);
      return true;
    }
    return false;
  };

  const cache: TtlCache = {
    set(key, value, nowMs, ttlMs = DEFAULT_TTL) {
      const expiresAt = nowMs + ttlMs;
      store.set(key, { value, expiresAt });
    },
    get(key, nowMs) {
      if (cleanIfExpired(key, nowMs)) return undefined;
      const entry = store.get(key);
      return entry ? entry.value : undefined;
    },
    has(key, nowMs) {
      if (cleanIfExpired(key, nowMs)) return false;
      return store.has(key);
    },
    delete(key) {
      return store.delete(key);
    },
    size(nowMs) {
      let count = 0;
      for (const [key, entry] of store.entries()) {
        if (nowMs >= entry.expiresAt) {
          store.delete(key);
        } else {
          count++;
        }
      }
      return count;
    },
    clear() {
      store.clear();
    },
  };

  return cache;
}

export interface TtlCache {
  set(key: string, value: unknown, nowMs: number, ttlMs?: number): void;
  get(key: string, nowMs: number): unknown;
  has(key: string, nowMs: number): boolean;
  delete(key: string): boolean;
  size(nowMs: number): number;
  clear(): void;
}
