      if (n === 0) {
        throw new Error('Division by zero');
      }
      currentValue /= n;
      return calculator;
    },
    clear: () => {
      currentValue = 0;
      return calculator;
    },
    result: () => currentValue,
    memoryStore: () => {
      memoryValue = currentValue;
      return calculator;
    },
    memoryAdd: () => {
      memoryValue += currentValue;
      return calculator;
    },
    memoryClear: () => {
      memoryValue = 0;
      return calculator;
    },
    memoryRecall: () => memoryValue,
  };

  return calculator;
}

