type Listener = (...args: any[]) => any;
type ListenerEntry = { fn: Listener; once: boolean };

export function createEventEmitter() {
  const events = new Map<string, ListenerEntry[]>();

  const on = (event: string, fn: Listener) => {
    const arr = events.get(event) ?? [];
    arr.push({ fn, once: false });
    events.set(event, arr);
  };

  const once = (event: string, fn: Listener) => {
    const arr = events.get(event) ?? [];
    arr.push({ fn, once: true });
    events.set(event, arr);
  };

  const off = (event: string, fn: Listener) => {
    const arr = events.get(event);
    if (!arr) return;
    for (let i = 0; i < arr.length; i++) {
      if (arr[i].fn === fn) {
        arr.splice(i, 1);
        if (arr.length === 0) events.delete(event);
        else events.set(event, arr);
        return;
      }
    }
  };

  const emit = (event: string, ...args: any[]) => {
    const arr = events.get(event);
    if (!arr) return [];
    const results: any[] = [];
    const remaining: ListenerEntry[] = [];
    for (const entry of arr) {
      const res = entry.fn(...args);
      results.push(res);
      if (!entry.once) remaining.push(entry);
    }
    if (remaining.length === 0) events.delete(event);
    else events.set(event, remaining);
    return results;
  };

  return { on, once, off, emit };
}

export type Listener = (payload: unknown) => unknown;

export interface EventEmitter {
  on(event: string, listener: Listener): number;
  once(event: string, listener: Listener): number;
  off(event: string, listener: Listener): boolean;
  emit(event: string, payload: unknown): unknown[];
  listenerCount(event: string): number;
}

export function createEventEmitter(): EventEmitter {
  const listeners = new Map<string, Array<{ listener: Listener; once: boolean }>>();

  const on = (event: string, listener: Listener): number => {
    const arr = listeners.get(event) ?? [];
    arr.push({ listener, once: false });
    listeners.set(event, arr);
    return arr.length;
  };

  const once = (event: string, listener: Listener): number => {
    const arr = listeners.get(event) ?? [];
    arr.push({ listener, once: true });
    listeners.set(event, arr);
    return arr.length;
  };

  const off = (event: string, listener: Listener): boolean => {
    const arr = listeners.get(event);
    if (!arr) return false;
    const index = arr.findIndex((r) => r.listener === listener);
    if (index === -1) return false;
    arr.splice(index, 1);
    if (arr.length === 0) {
      listeners.delete(event);
    } else {
      listeners.set(event, arr);
    }
    return true;
  };

  const emit = (event: string, payload: unknown): unknown[] => {
    const arr = listeners.get(event);
    if (!arr) return [];
    const results: unknown[] = [];
    const toCall = [...arr];
    for (const { listener, once } of toCall) {
      results.push(listener(payload));
      if (once) {
        const idx = arr.findIndex((r) => r.listener === listener && r.once);
        if (idx !== -1) {
          arr.splice(idx, 1);
        }
      }
    }
    if (arr.length === 0) {
      listeners.delete(event);
    }
    return results;
  };

  const listenerCount = (event: string): number => {
    const arr = listeners.get(event);
    return arr ? arr.length : 0;
  };

  return { on, once, off, emit, listenerCount };
}

export function createRateLimiter() {
  const data = new Map<string, number[]>();
  const MAX_REQUESTS = 3;
  const WINDOW_MS = 1000;

  function tryRequest(key: string, nowMs: number): boolean {
    let timestamps = data.get(key) ?? [];
    // Remove timestamps outside the current window
    timestamps = timestamps.filter((ts) => ts > nowMs - WINDOW_MS);
    if (timestamps.length < MAX_REQUESTS) {
      timestamps.push(nowMs);
      data.set(key, timestamps);
      return true;
    } else {
      data.set(key, timestamps);
      return false;
    }
  }

  function reset(key: string): void {
    data.delete(key);
  }

  return {
    tryRequest,
    reset,
  };
}

export interface RateLimiter {
  allow(key: string, nowMs: number): boolean;
  remaining(key: string, nowMs: number): number;
  reset(key: string): void;
}

export function createRateLimiter(): RateLimiter {
  const limit = 3;
  const windowMs = 1000;
  const state = new Map<string, { windowStart: number; count: number }>();

  const allow = (key: string, nowMs: number): boolean => {
    let entry = state.get(key);
    if (!entry) {
      entry = { windowStart: nowMs, count: 0 };
      state.set(key, entry);
    }
    if (nowMs - entry.windowStart >= windowMs) {
      entry.windowStart = nowMs;
      entry.count = 0;
    }
    if (entry.count < limit) {
      entry.count += 1;
      return true;
    }
    return false;
  };

  const remaining = (key: string, nowMs: number): number => {
    let entry = state.get(key);
    if (!entry) {
      return limit;
    }
    if (nowMs - entry.windowStart >= windowMs) {
      entry.windowStart = nowMs;
      entry.count = 0;
    }
    const rem = limit - entry.count;
    return rem >= 0 ? rem : 0;
  };

  const reset = (key: string): void => {
    state.delete(key);
  };

  return { allow, remaining, reset };
}

