export function createTtlCache() {
  const store = new Map<string, { value: unknown; expiresAt: number }>();

  function set(
    key: string,
    value: unknown,
    nowMs: number,
    ttlMs?: number
  ): void {
    const expiresAt = nowMs + (ttlMs ?? 1000);
    store.set(key, { value, expiresAt });
  }

  function get(key: string, nowMs: number): unknown {
    const item = store.get(key);
    if (!item) return undefined;
    if (nowMs >= item.expiresAt) {
      store.delete(key);
      return undefined;
    }
    return item.value;
  }

  function has(key: string, nowMs: number): boolean {
    const item = store.get(key);
    if (!item) return false;
    if (nowMs >= item.expiresAt) {
      store.delete(key);
      return false;
    }
    return true;
  }

  function deleteKey(key: string): boolean {
    return store.delete(key);
  }

  function size(nowMs: number): number {
    let count = 0;
    for (const [_, item] of store.entries()) {
      if (nowMs >= item.expiresAt) {
        store.delete(item);
        continue;
      }
      count++;
    }
    return count;
  }

  function clear(): void {
    store.clear();
  }

  return {
    set,
    get,
    has,
    delete: deleteKey,
    size,
    clear,
  };
}

